export type LocalCopy = {en:string;fr:string};
const t=(en:string,fr:string):LocalCopy=>({en,fr});
export type MarketChapter={id:string;title:LocalCopy;goal:LocalCopy;sections:{title:LocalCopy;body:LocalCopy}[];terms:{term:LocalCopy;definition:LocalCopy}[];formula:LocalCopy;example:LocalCopy;flow:LocalCopy[];mistake:LocalCopy;question:LocalCopy;options:LocalCopy[];correct:number;feedback:LocalCopy;lesson:string;visual:"price"|"curve"|"equity"|"fx"|"risk"|"credit"|"allocation"|"none"};
export const marketChapters:MarketChapter[]=[
{id:"market-basics",title:t("1 · What a market actually does","1 · À quoi sert un marché"),goal:t("Follow money, ownership and risk from an issuer to an investor.","Suivre l’argent, la propriété et le risque de l’émetteur à l’investisseur."),sections:[
{title:t("Claims on real economic activity","Des droits sur une activité économique réelle"),body:t("A financial instrument is a contract or ownership claim. A share gives an ownership interest in a business; a bond is a debt claim with contractual payments; a derivative links its payoff to an underlying variable. These instruments transfer capital and risk between people who have different needs. A company may need funding today, while an investor is willing to postpone consumption in exchange for an uncertain return.","Un instrument financier est un contrat ou un droit de propriété. Une action représente une part d’entreprise ; une obligation est une créance avec des paiements contractuels ; un produit dérivé lie son résultat à une variable sous-jacente. Ces instruments transfèrent capital et risque entre acteurs aux besoins différents. Une entreprise cherche un financement aujourd’hui ; un investisseur accepte de reporter sa consommation contre un rendement incertain.")},
{title:t("Primary and secondary markets","Marché primaire et marché secondaire"),body:t("In the primary market, a new security is sold and proceeds go to the issuer, after fees. In the secondary market, existing securities trade between investors: buying an existing share normally pays the seller, not the company. A liquid secondary market can still help companies raise capital because investors value the ability to sell later. An exchange organizes trading; a broker transmits orders; a dealer may trade from its own inventory.","Sur le marché primaire, un nouveau titre est émis : le produit de la vente revient à l’émetteur, après frais. Sur le secondaire, des titres existants circulent entre investisseurs : acheter une action existante rémunère normalement le vendeur, pas l’entreprise. La liquidité du secondaire facilite néanmoins les émissions, car les investisseurs valorisent la possibilité de revendre. Une bourse organise les échanges ; un courtier transmet les ordres ; un teneur de marché peut négocier sur son propre stock.")},
{title:t("Price is a meeting point, not a guarantee","Le prix est un point de rencontre, pas une garantie"),body:t("Every transaction has a buyer and seller. Prices move when the terms on which participants will trade change, not because buyers exist without sellers. Information, financing constraints, liquidity needs and expectations all matter. Market capitalization is a current marginal price multiplied by shares outstanding; it is not a cash balance and does not mean the entire company could be sold at that price immediately.","Toute transaction a un acheteur et un vendeur. Le prix change lorsque les conditions auxquelles les participants acceptent d’échanger changent. Information, contraintes de financement, besoin de liquidité et anticipations comptent. La capitalisation boursière est le prix marginal actuel multiplié par le nombre d’actions ; ce n’est pas une réserve de trésorerie et cela ne garantit pas qu’on puisse vendre toute l’entreprise à ce prix immédiatement.")}
],terms:[{term:t("Liquidity","Liquidité"),definition:t("Ability to trade a meaningful amount promptly with limited price impact.","Capacité d’échanger un montant significatif rapidement avec un impact limité sur le prix.")},{term:t("Price discovery","Formation des prix"),definition:t("Process through which orders and information establish a tradable price.","Processus par lequel ordres et informations établissent un prix négociable.")}],formula:t("Market capitalization = share price × shares outstanding","Capitalisation boursière = prix de l’action × actions en circulation"),example:t("Illustration: a firm issues 1 million new shares at $20: gross new funding is $20 million. Later, 100 shares trade at $22: the seller receives $2,200 before fees; the company receives no new funds from that trade.","Illustration : émission d’un million d’actions à 20 $ : financement brut de 20 M$. Ensuite, 100 actions s’échangent à 22 $ : le vendeur reçoit 2 200 $ avant frais ; l’entreprise ne reçoit pas de nouveau financement sur cet échange."),flow:[t("Issuer needs capital","L’émetteur cherche du capital"),t("Primary issuance funds activity","L’émission primaire finance l’activité"),t("Investors trade existing claims","Les investisseurs échangent les titres existants"),t("New information changes the tradable price","L’information modifie le prix négociable")],mistake:t("A rising market capitalization is not cash flowing into the company.","Une hausse de capitalisation n’est pas une entrée de trésorerie pour l’entreprise."),question:t("Who receives the money when you buy an existing share from another investor?","Qui reçoit l’argent quand tu achètes une action existante à un investisseur ?"),options:[t("The seller","Le vendeur"),t("Always the company","Toujours l’entreprise"),t("The central bank","La banque centrale")],correct:0,feedback:t("Secondary trading transfers ownership between investors. New issuance is the separate funding transaction.","Le secondaire transfère la propriété entre investisseurs. L’émission constitue l’opération de financement distincte."),lesson:"year-1-financial-system-market-structure",visual:"none"},
{id:"read-a-quote",title:t("2 · Read a quote without confusing units","2 · Lire une cotation sans confondre les unités"),goal:t("Separate level, change, return, yield and observation date.","Distinguer niveau, variation, rendement, taux et date d’observation."),sections:[
{title:t("A useful observation needs a label and a clock","Une observation utile a un nom et une date"),body:t("Before explaining a number, identify the instrument, currency, unit, observation date, source and comparison window. An equity index level is measured in index points; a Treasury yield is an annualized rate; an FX pair is one currency per unit of another. A quote from yesterday cannot explain a move that occurred an hour ago without additional evidence. Refresh time tells you when the app fetched data, not when the underlying market traded.","Avant d’expliquer un chiffre, identifie instrument, devise, unité, date d’observation, source et période de comparaison. Un indice actions s’exprime en points ; un rendement Treasury est un taux annualisé ; une paire de change exprime une devise par unité de l’autre. Une observation d’hier ne suffit pas à expliquer un mouvement d’il y a une heure. L’heure de rafraîchissement indique quand l’application a chargé les données, pas quand le marché a coté.")},
{title:t("Percent is different from percentage points","Pourcentage et points de pourcentage"),body:t("A yield rising from 4% to 4.5% increases by 0.5 percentage point or 50 basis points, but by 12.5% relative to its initial level. In rates discussions, the 50 bp description is usually the useful one. An index rising from 100 to 105 gains 5 points and 5%; from 200 to 205 it gains the same 5 points but only 2.5%. Price return excludes distributions; total return includes distributions under the stated reinvestment convention.","Un taux passant de 4 % à 4,5 % augmente de 0,5 point de pourcentage ou 50 points de base, mais de 12,5 % relativement à sa valeur initiale. Pour les taux, les 50 bps sont généralement l’information utile. Un indice passant de 100 à 105 gagne 5 points et 5 % ; de 200 à 205, il gagne aussi 5 points mais seulement 2,5 %. Le rendement en prix exclut les distributions ; le rendement total les inclut selon la convention de réinvestissement indiquée.")},
{title:t("Bid, ask and execution","Cours acheteur, vendeur et exécution"),body:t("The bid is a price a buyer is offering; the ask is a price a seller requests. A market buy generally executes against available asks, potentially at several prices for a large order. A limit order controls the worst acceptable price but may never fill. A displayed midpoint is not an executable promise. Trading costs include the spread, fees and market impact, which can grow in stressed or illiquid markets.","Le bid est le prix proposé à l’achat ; l’ask est le prix demandé à la vente. Un achat au marché consomme les offres disponibles, parfois à plusieurs prix pour un ordre important. Un ordre à cours limité contrôle le prix maximal accepté mais peut ne jamais être exécuté. Le milieu de fourchette n’est pas une promesse d’exécution. Les coûts comprennent fourchette, frais et impact de marché, qui peuvent augmenter en période de stress.")}
],terms:[{term:t("Basis point (bp)","Point de base (bp)"),definition:t("0.01 percentage point, or 0.0001 in decimal rate units.","0,01 point de pourcentage, soit 0,0001 en taux décimal.")},{term:t("Bid–ask spread","Fourchette acheteur–vendeur"),definition:t("Ask minus bid, a trading-cost indicator distinct from a credit spread.","Ask moins bid : indicateur de coût de transaction, distinct d’un spread de crédit.")}],formula:t("Return = (ending price / initial price − 1) × 100%; yield change in bps = (new yield % − old yield %) × 100","Rendement = (prix final / prix initial − 1) × 100 % ; variation en bps = (nouveau taux % − ancien taux %) × 100"),example:t("Hypothetical bid $99.90 / ask $100.10: the spread is $0.20. Buying then immediately selling at unchanged quotes loses $0.20 per share before fees. It is not a free trade simply because commissions are zero.","Bid hypothétique 99,90 $ / ask 100,10 $ : fourchette de 0,20 $. Acheter puis revendre immédiatement à cotations inchangées perd 0,20 $ par action avant frais. Une commission nulle n’implique pas un échange sans coût."),flow:[t("Identify instrument and units","Identifier instrument et unités"),t("Check observation and comparison dates","Vérifier dates et comparaison"),t("Calculate the move correctly","Calculer correctement la variation"),t("Only then investigate the cause","Chercher ensuite la cause")],mistake:t("Do not label a 50 bp rate rise as a 50% increase.","Ne présente pas une hausse de taux de 50 bps comme une hausse de 50 %."),question:t("A yield rises from 3.80% to 4.05%. What is the move?","Un taux passe de 3,80 % à 4,05 %. Quelle variation ?"),options:[t("+25 bps","+25 bps"),t("+0.25 bps","+0,25 bp"),t("+25 percentage points","+25 points de pourcentage")],correct:0,feedback:t("4.05 − 3.80 = 0.25 percentage point; multiply by 100 to get 25 bps.","4,05 − 3,80 = 0,25 point ; multiplier par 100 donne 25 bps."),lesson:"year-1-stocks-bonds-etfs-funds",visual:"none"},
{id:"bond-math",title:t("3 · Bonds, yields and duration","3 · Obligations, rendements et duration"),goal:t("Explain the inverse price–yield relation and calculate a rate sensitivity.","Expliquer la relation inverse prix–taux et calculer une sensibilité."),sections:[
{title:t("Discount a contractual cash-flow stream","Actualiser les flux contractuels"),body:t("A conventional fixed-rate bond promises coupons and repayment of principal. Its price is the present value of these payments using the return investors currently require. The coupon rate is fixed by the contract; current yield divides annual coupon by the current price; yield to maturity is the rate equating all promised payments to the price under the relevant convention. These are different concepts. Yield to maturity assumes contractual payments occur; it does not guarantee the realized return if default, early sale or reinvestment conditions change.","Une obligation classique à taux fixe promet des coupons et le remboursement du principal. Son prix est la valeur actuelle de ces paiements au rendement exigé aujourd’hui. Le coupon est contractuel ; le rendement courant divise le coupon annuel par le prix ; le rendement à échéance est le taux qui égalise tous les paiements promis avec le prix selon la convention retenue. Ces notions diffèrent. Le rendement à échéance suppose les paiements promis ; il ne garantit pas le rendement réalisé en cas de défaut, revente anticipée ou changement des conditions de réinvestissement.")},
{title:t("Why price falls when yield rises","Pourquoi le prix baisse lorsque le taux monte"),body:t("Imagine receiving $100 exactly one year from now with no coupon and no credit loss. At a 4% required return, the price is 100 / 1.04 = $96.15. At 5%, it is 100 / 1.05 = $95.24. The promised $100 did not change; the price did. More distant payments are generally more sensitive to a discount-rate change. A government guarantee on contractual repayment does not protect a bond’s resale price before maturity.","Imagine recevoir 100 $ dans exactement un an, sans coupon ni perte de crédit. À 4 % de rendement exigé, le prix vaut 100 / 1,04 = 96,15 $. À 5 %, il vaut 100 / 1,05 = 95,24 $. Les 100 $ promis n’ont pas changé ; le prix a changé. Les paiements lointains sont généralement plus sensibles au taux d’actualisation. Une garantie publique de remboursement ne protège pas le prix de revente avant échéance.")},
{title:t("Duration is a sensitivity, not just maturity","La duration est une sensibilité"),body:t("Modified duration estimates proportional price sensitivity to a small yield change. A duration of 6 implies roughly −6% for a +1 percentage-point yield shift, holding other factors constant. Convexity captures curvature and improves the approximation for larger moves. Different curve points can move differently: one duration number assumes a simplified parallel shift. Credit spreads, embedded options and liquidity can also move the price, so a duration estimate is not a complete risk model.","La duration modifiée estime la sensibilité proportionnelle du prix à une petite variation du rendement. Une duration de 6 implique environ −6 % pour une hausse d’un point, toutes choses égales par ailleurs. La convexité corrige la courbure pour de plus grands mouvements. Les maturités ne bougent pas toujours ensemble : un chiffre de duration suppose un déplacement parallèle simplifié. Spreads de crédit, options incorporées et liquidité influencent aussi le prix : la duration n’est pas un modèle complet du risque.")}
],terms:[{term:t("Coupon","Coupon"),definition:t("Contractual interest payment, distinct from yield.","Paiement contractuel d’intérêt, distinct du rendement.")},{term:t("Modified duration","Duration modifiée"),definition:t("First-order price sensitivity to a yield change.","Sensibilité du prix de premier ordre à une variation du rendement.")}],formula:t("ΔP / P ≈ −Dmod × Δy, where Δy is a decimal rate change (50 bps = 0.005).","ΔP / P ≈ −Dmod × Δy, avec Δy en taux décimal (50 bps = 0,005)."),example:t("Hypothetical $10,000 position, duration 6, yield +50 bps: proportional change ≈ −6 × 0.005 = −0.03, or −3%. Estimated value $9,700, before convexity, coupon accrual, spread moves and costs.","Position hypothétique de 10 000 $, duration 6, taux +50 bps : variation ≈ −6 × 0,005 = −0,03, soit −3 %. Valeur estimée 9 700 $, avant convexité, coupon couru, spreads et coûts."),flow:[t("Required yield rises","Le rendement exigé monte"),t("Fixed cash flows are discounted more heavily","Les flux fixes sont davantage actualisés"),t("Present value falls","La valeur actuelle baisse")],mistake:t("A low-duration bond can still have substantial default or liquidity risk.","Une obligation à faible duration peut avoir un risque de défaut ou de liquidité important."),question:t("Duration 8, yield +25 bps: approximate price change?","Duration 8, taux +25 bps : variation approximative du prix ?"),options:[t("−2%","−2 %"),t("+2%","+2 %"),t("−200%","−200 %")],correct:0,feedback:t("−8 × 0.0025 = −0.02 = −2%. This approximation holds other risks constant.","−8 × 0,0025 = −0,02 = −2 %. Cette approximation suppose les autres risques inchangés."),lesson:"year-2-duration-convexity",visual:"price"},
{id:"yield-curve",title:t("4 · Read the whole yield curve","4 · Lire toute la courbe des taux"),goal:t("Distinguish inversion, steepening, flattening and the forces behind them.","Distinguer inversion, pentification, aplatissement et leurs moteurs."),sections:[
{title:t("A curve compares maturities at one time","Une courbe compare les échéances à une date"),body:t("The yield curve plots yield against maturity for comparable securities at the same observation date. The 2-year Treasury yield is often especially sensitive to the expected near-term policy path. The 10-year yield also contains expectations of future short rates plus a term premium compensating investors for holding duration. Inflation expectations, growth prospects, bond supply, demand and uncertainty can all affect it. A nominal yield is not the same as a real yield after inflation.","La courbe place le rendement en fonction de l’échéance pour des titres comparables à la même date. Le Treasury 2 ans est souvent sensible à la trajectoire monétaire proche. Le 10 ans reflète les taux courts futurs anticipés et une prime de terme rémunérant la détention de duration. Inflation anticipée, croissance, offre obligataire, demande et incertitude l’influencent. Un taux nominal n’est pas un taux réel après inflation.")},
{title:t("Calculate the slope before naming the move","Calculer la pente avant de nommer le mouvement"),body:t("The 2s10s spread equals the 10-year yield minus the 2-year yield. A negative result is an inversion at those two points. Steepening means this spread becomes more positive, even if it remains negative. Flattening means it becomes less positive or more negative. Bull describes falling yields and rising bond prices; bear describes rising yields and falling bond prices. The level and slope are distinct dimensions of the curve.","Le spread 2s10s égale le taux 10 ans moins le taux 2 ans. Un résultat négatif signifie une inversion entre ces points. La pentification rend ce spread plus positif, même s’il reste négatif. L’aplatissement le rend moins positif ou plus négatif. Bull décrit la baisse des rendements et la hausse des prix obligataires ; bear décrit l’inverse. Niveau et pente sont deux dimensions distinctes.")},
{title:t("Four patterns, different stories","Quatre configurations, des histoires différentes"),body:t("Bull steepening: short yields fall more than long yields, sometimes on expected cuts. Bear steepening: long yields rise more than short yields, possibly on inflation or term premium. Bull flattening: long yields fall more. Bear flattening: short yields rise more, possibly on tighter policy expectations. These are descriptions, not proven causes. An inversion can be a warning about expectations and policy tightness, but is neither a precise recession clock nor proof that every risk asset must immediately fall.","Bull steepening : les taux courts baissent davantage, parfois avec des baisses de taux anticipées. Bear steepening : les taux longs montent davantage, éventuellement avec inflation ou prime de terme. Bull flattening : les taux longs baissent davantage. Bear flattening : les taux courts montent davantage, parfois avec une politique plus restrictive anticipée. Ces noms décrivent, sans prouver la cause. Une inversion peut signaler des attentes et un resserrement, mais n’est ni une horloge de récession ni la preuve d’une baisse immédiate de tous les actifs risqués.")}
],terms:[{term:t("Term premium","Prime de terme"),definition:t("Additional compensation for uncertainty from holding a longer-maturity bond.","Rémunération supplémentaire pour l’incertitude liée à une obligation longue.")},{term:t("Inversion","Inversion"),definition:t("A shorter-maturity yield exceeds a longer-maturity yield at the selected points.","Le rendement court dépasse le rendement long aux points considérés.")}],formula:t("2s10s in bps = (10Y yield % − 2Y yield %) × 100","2s10s en bps = (taux 10 ans % − taux 2 ans %) × 100"),example:t("Illustration: initially 2Y 4.50%, 10Y 4.00% gives −50 bps. Later 2Y 4.00%, 10Y 3.80% gives −20 bps. Both yields fell and the short end fell more: bull steepening by 30 bps, while still inverted.","Illustration : 2 ans 4,50 %, 10 ans 4,00 % : −50 bps. Ensuite 2 ans 4,00 %, 10 ans 3,80 % : −20 bps. Les deux taux baissent, le court davantage : bull steepening de 30 bps, avec une courbe encore inversée."),flow:[t("Observe both endpoints","Observer les deux échéances"),t("Calculate each yield change","Calculer chaque variation"),t("Compare the old and new spread","Comparer ancienne et nouvelle pente"),t("Investigate expectations and term premium","Étudier anticipations et prime de terme")],mistake:t("A steepening curve does not necessarily mean yields rose.","Une courbe qui se pentifie n’implique pas forcément des taux en hausse."),question:t("2Y falls 40 bps; 10Y falls 10 bps. Name the move.","Le 2 ans baisse de 40 bps ; le 10 ans de 10 bps. Quel mouvement ?"),options:[t("Bull steepening","Bull steepening"),t("Bear steepening","Bear steepening"),t("Bull flattening","Bull flattening")],correct:0,feedback:t("Both yields fall (bull) and 10Y minus 2Y increases by 30 bps (steepening).","Les rendements baissent (bull) et 10 ans moins 2 ans augmente de 30 bps (pentification)."),lesson:"year-2-fixed-income-yield-curves",visual:"curve"},
{id:"equities",title:t("5 · Equities: earnings, multiples and indices","5 · Actions : bénéfices, multiples et indices"),goal:t("Separate a business improvement from a change in the price paid for it.","Distinguer amélioration d’entreprise et changement du prix payé."),sections:[
{title:t("A share prices future expectations","Une action valorise des anticipations"),body:t("A company’s equity value depends on the cash flows shareholders may ultimately receive, their timing and risk. Revenue growth matters only through its impact on margins, reinvestment and future cash generation. Profits and cash flow differ because working capital, capital expenditure and non-cash accounting charges matter. A company can beat last year’s earnings and still disappoint investors if its outlook is weaker than the expectations built into the price.","La valeur des capitaux propres dépend des flux qui pourront revenir aux actionnaires, de leur calendrier et du risque. La croissance du chiffre d’affaires compte via les marges, les investissements et la trésorerie future. Résultat et cash flow diffèrent à cause du besoin en fonds de roulement, des investissements et des charges sans décaissement. Une entreprise peut dépasser ses bénéfices de l’an dernier et décevoir si les perspectives sont inférieures aux attentes déjà intégrées au prix.")},
{title:t("Multiples summarize assumptions","Les multiples résument des hypothèses"),body:t("The price-to-earnings ratio divides price per share by earnings per share. Forward and trailing earnings are not interchangeable. A higher multiple may reflect better growth, quality or lower risk; it may also reflect optimism that later proves excessive. Compare companies with similar accounting, capital intensity and earnings durability. Enterprise value includes claims of debt and equity capital providers; EV/EBITDA and P/E use different numerators and denominators and should not be mixed.","Le ratio cours/bénéfice divise le prix par le bénéfice par action. Bénéfices futurs et passés ne sont pas interchangeables. Un multiple élevé peut refléter croissance, qualité ou risque plus faible, mais aussi un optimisme excessif. Compare des comptabilités, intensités capitalistiques et durabilités de bénéfices proches. La valeur d’entreprise couvre apporteurs de dette et de capitaux propres ; EV/EBITDA et P/E ont des numérateurs et dénominateurs distincts à ne pas mélanger.")},
{title:t("The index can hide dispersion","L’indice peut masquer la dispersion"),body:t("An index is a rules-based basket, not a single company. In a capitalization-weighted index, the largest constituents have the greatest influence. A rising headline index can coexist with a majority of stocks declining if a few heavyweights rise strongly. Breadth describes participation across constituents; sector performance helps explain whether moves are broad or concentrated. Compare total-return indices consistently and remember that foreign investment returns also depend on currency.","Un indice est un panier régi par des règles, pas une entreprise. Dans un indice pondéré par capitalisation, les plus grosses valeurs influencent davantage le résultat. L’indice peut monter tandis qu’une majorité de titres baisse si quelques poids lourds progressent. La breadth mesure la participation des valeurs ; les secteurs montrent la concentration du mouvement. Compare des indices de rendement total cohérents et n’oublie pas l’effet de change d’un investissement étranger.")}
],terms:[{term:t("EPS · earnings per share","BPA · bénéfice par action"),definition:t("Earnings attributable to common shareholders divided by the relevant share count.","Résultat attribuable aux actionnaires ordinaires divisé par le nombre d’actions pertinent.")},{term:t("Multiple compression","Compression du multiple"),definition:t("A fall in the valuation multiple investors are willing to pay.","Baisse du multiple de valorisation accepté par les investisseurs.")}],formula:t("Simplified share price = expected EPS × forward P/E","Prix simplifié = BPA attendu × P/E prospectif"),example:t("Hypothetical EPS rises from $5 to $5.50 (+10%), but P/E falls from 20× to 17×. Price goes from $100 to $93.50: −6.5%. Stronger earnings did not offset a lower multiple. This identity explains a price change; it does not establish fair value.","BPA hypothétique de 5 $ à 5,50 $ (+10 %), mais P/E de 20× à 17× : le prix passe de 100 $ à 93,50 $, soit −6,5 %. Les bénéfices n’ont pas compensé la baisse du multiple. Cette identité décompose le prix ; elle ne démontre pas une juste valeur."),flow:[t("Revenue and cost outlook","Perspectives de revenus et de coûts"),t("Expected earnings and cash flows","Bénéfices et cash flows attendus"),t("Required return and valuation multiple","Rendement exigé et multiple"),t("Share price and index contribution","Prix de l’action et contribution à l’indice")],mistake:t("Cheap per share is not the same as cheaply valued: a $5 share can have a higher P/E than a $500 share.","Une action à 5 $ n’est pas nécessairement moins chère en valorisation qu’une action à 500 $."),question:t("EPS $4, P/E 25×: implied price?","BPA 4 $, P/E 25× : prix implicite ?"),options:[t("$100","100 $"),t("$6.25","6,25 $"),t("$29","29 $")],correct:0,feedback:t("$4 × 25 = $100. The multiple embeds growth and risk assumptions that still need testing.","4 $ × 25 = 100 $. Il faut encore tester les hypothèses de croissance et de risque du multiple."),lesson:"year-2-equity-valuation",visual:"equity"},
{id:"fx",title:t("6 · Currencies and cross-border returns","6 · Devises et rendements internationaux"),goal:t("Read pair direction, exchange arithmetic and the distinction between hedging and prediction.","Lire les paires, calculer une conversion et distinguer couverture et prévision."),sections:[
{title:t("Name the base and quote currencies","Nommer devise de base et devise de cotation"),body:t("EUR/USD = 1.10 means one euro buys $1.10: EUR is the base and USD the quote currency. A rise to 1.20 means the euro strengthens against the dollar. USD/JPY uses the opposite dollar convention: a rise means dollar appreciation against the yen. Always identify the pair before saying the dollar rose. Currency indices summarize a basket and can move differently from an individual pair.","EUR/USD = 1,10 signifie qu’un euro achète 1,10 dollar : EUR est la base, USD la devise de cotation. Une hausse à 1,20 signifie un euro plus fort face au dollar. USD/JPY a une convention différente : une hausse signifie un dollar plus fort face au yen. Identifie toujours la paire avant de parler de hausse du dollar. Un indice de devise résume un panier et peut diverger d’une paire précise.")},
{title:t("Relative expectations drive capital flows","Les attentes relatives influencent les flux"),body:t("Currency prices reflect relative policy expectations, growth, inflation, external balances, risk demand and capital flows. Higher expected domestic rates may support a currency, but the reason for higher rates matters: compensation for inflation or default risk can coexist with depreciation. An expected rate increase may already be priced in. Spot exchange rates, forward rates and interest differentials are connected, but a forward rate is not a guaranteed forecast of future spot.","Les devises reflètent anticipations monétaires relatives, croissance, inflation, balances extérieures, demande de sécurité et flux de capitaux. Des taux domestiques plus élevés peuvent soutenir une devise, mais leur cause compte : une rémunération accrue du risque d’inflation ou de défaut peut coexister avec une dépréciation. Une hausse attendue peut déjà être intégrée. Comptant, taux à terme et différentiels d’intérêt sont liés, mais le taux à terme n’est pas une prévision garantie du comptant futur.")},
{title:t("Translate the investment and the currency separately","Séparer investissement et effet de change"),body:t("For a euro investor holding a dollar asset, the euro value equals dollar value divided by EUR/USD. A stronger euro reduces the euro value of an unchanged dollar asset. Hedging can reduce a specific FX exposure using forwards or other instruments, but introduces costs, collateral requirements or residual basis risk. ECB reference rates are daily informational observations, not executable dealing quotes.","Pour un investisseur en euros détenant un actif en dollars, la valeur en euros égale la valeur en dollars divisée par EUR/USD. Un euro plus fort réduit la valeur en euros d’un actif dollar inchangé. Une couverture par contrats à terme ou autres instruments peut réduire ce risque, avec coûts, garanties ou risque de base résiduel. Les taux de référence BCE sont des observations quotidiennes d’information, pas des prix d’exécution.")}
],terms:[{term:t("Base currency","Devise de base"),definition:t("First currency in the pair, expressed as one unit.","Première devise de la paire, exprimée pour une unité.")},{term:t("Hedge","Couverture"),definition:t("Position designed to offset a specified risk exposure, not remove every risk.","Position destinée à compenser une exposition précise, pas tous les risques.")}],formula:t("EUR value of USD asset = USD asset value / EUR/USD","Valeur EUR d’un actif USD = valeur USD / EUR/USD"),example:t("Hypothetical $1,100 asset: at EUR/USD 1.10 it is worth €1,000. At 1.20, with unchanged dollar price, it is worth €916.67 (−8.33%). Currency effects can reverse or amplify local-market returns.","Actif hypothétique de 1 100 $ : à EUR/USD 1,10 il vaut 1 000 €. À 1,20, prix dollar inchangé, il vaut 916,67 € (−8,33 %). Le change peut inverser ou amplifier un rendement local."),flow:[t("Policy surprise relative to another country","Surprise monétaire relative"),t("Interest differential and capital flows may change","Différentiel de taux et flux peuvent changer"),t("Exchange rate reprices","Le taux de change s’ajuste"),t("Foreign revenue and investment returns translate differently","Revenus étrangers et investissements changent de valeur convertie")],mistake:t("A currency’s nominal unit size does not measure how strong its economy is.","La taille nominale d’une unité de devise ne mesure pas la force de l’économie."),question:t("EUR/USD rises. What happens to the euro value of a fixed $1,000 asset?","EUR/USD monte. Que devient la valeur en euros d’un actif fixe de 1 000 $ ?"),options:[t("It falls","Elle baisse"),t("It rises","Elle monte"),t("It cannot change","Elle ne peut pas changer")],correct:0,feedback:t("Divide the fixed dollar amount by a larger EUR/USD rate: fewer euros.","Diviser les dollars fixes par un EUR/USD plus grand donne moins d’euros."),lesson:"year-2-fx-international-finance",visual:"fx"},
{id:"credit",title:t("7 · Credit: default, spreads and refinancing","7 · Crédit : défaut, spreads et refinancement"),goal:t("Separate government-rate risk from corporate credit risk.","Séparer risque de taux et risque de crédit d’entreprise."),sections:[
{title:t("A corporate bond carries several risks","Une obligation d’entreprise porte plusieurs risques"),body:t("An investor lending to a company requires compensation for time, expected default losses, uncertainty and liquidity. The corporate yield can be viewed approximately as a matched government or reference yield plus a credit spread. Matching maturity and optionality matters. A higher yield is not automatically a better bargain: it may simply compensate for a greater probability of loss. Credit analysis examines cash flow, leverage, interest coverage, collateral, covenants and the maturity schedule.","Prêter à une entreprise exige une rémunération du temps, des pertes de défaut attendues, de l’incertitude et de la liquidité. On peut approximer son rendement par un taux de référence comparable plus un spread. Il faut tenir compte de l’échéance et des options. Un rendement élevé n’est pas automatiquement une bonne affaire : il peut rémunérer une forte probabilité de perte. L’analyse étudie cash flow, levier, couverture des intérêts, garanties, clauses et échéancier de dette.")},
{title:t("Investment grade, high yield and OAS","Catégorie investissement, haut rendement et OAS"),body:t("Investment grade generally starts at BBB− for S&P/Fitch or Baa3 for Moody’s; lower ratings are high yield. Ratings are opinions and can lag changing conditions. An option-adjusted spread attempts to remove the value of embedded options to compare credit compensation more consistently. Spreads also reflect liquidity and risk premiums, so they are not pure default probabilities. A widening spread is usually unfavorable for an existing corporate bond’s price, holding the reference curve fixed.","La catégorie investissement commence généralement à BBB− chez S&P/Fitch ou Baa3 chez Moody’s ; en dessous, on parle de haut rendement. Les notations sont des opinions et peuvent réagir tardivement. L’OAS ajuste la valeur des options incorporées pour comparer plus proprement la rémunération du crédit. Le spread reflète aussi liquidité et primes de risque : ce n’est pas une pure probabilité de défaut. Son élargissement pénalise généralement le prix d’une obligation existante, courbe de référence inchangée.")},
{title:t("Refinancing transmits markets into the business","Le refinancement transmet les marchés à l’entreprise"),body:t("A company with fixed-rate debt may not immediately pay higher interest when markets reprice. The effect grows as debt matures and must be refinanced, or if borrowing is floating-rate. Higher interest expense reduces cash available for reinvestment, debt reduction or shareholders. Companies with low liquidity buffers or near-term maturity walls can be more vulnerable. Debt/EBITDA and interest coverage are useful screens, but require consistent definitions and cannot replace a cash-flow forecast.","Une entreprise endettée à taux fixe ne paie pas immédiatement plus lorsque le marché évolue. L’effet apparaît au refinancement ou sur la dette à taux variable. Les intérêts supplémentaires réduisent les liquidités disponibles pour investir, rembourser ou rémunérer les actionnaires. Faibles réserves et grosses échéances proches augmentent la vulnérabilité. Dette/EBITDA et couverture des intérêts sont utiles, mais nécessitent des définitions cohérentes et ne remplacent pas une prévision de trésorerie.")}
],terms:[{term:t("Credit spread","Écart de crédit"),definition:t("Yield compensation above a comparable reference curve.","Rémunération au-dessus d’une courbe de référence comparable.")},{term:t("Interest coverage","Couverture des intérêts"),definition:t("Earnings or cash-flow measure divided by interest expense; specify the numerator.","Mesure de résultat ou cash flow divisée par les intérêts ; préciser le numérateur.")}],formula:t("Corporate yield ≈ reference yield + credit spread","Rendement d’entreprise ≈ taux de référence + spread de crédit"),example:t("Illustration: government yield 4%, spread 2% gives corporate yield about 6%. If government yield falls to 3.5% but spread widens to 3%, the corporate yield rises to 6.5%. A government-bond rally can coexist with corporate-bond losses.","Illustration : taux public 4 %, spread 2 % : rendement d’entreprise environ 6 %. Si le taux public tombe à 3,5 % mais le spread monte à 3 %, le rendement d’entreprise monte à 6,5 %. Une hausse des obligations d’État peut coexister avec une baisse des obligations d’entreprise."),flow:[t("Growth or issuer outlook weakens","Les perspectives se dégradent"),t("Investors demand a wider spread","Les investisseurs exigent un spread plus élevé"),t("Refinancing cost increases","Le coût de refinancement augmente"),t("Cash flow and equity risk can deteriorate","Cash flow et risque action peuvent se détériorer")],mistake:t("Treasury yields falling does not guarantee that all bond prices rise.","Une baisse des taux Treasury ne garantit pas une hausse de toutes les obligations."),question:t("Reference yield 3%, spread 250 bps: approximate corporate yield?","Taux de référence 3 %, spread 250 bps : rendement d’entreprise approximatif ?"),options:[t("5.5%","5,5 %"),t("253%","253 %"),t("3.25%","3,25 %")],correct:0,feedback:t("250 bps = 2.5 percentage points; 3% + 2.5% = 5.5%.","250 bps = 2,5 points ; 3 % + 2,5 % = 5,5 %."),lesson:"year-3-credit-analysis",visual:"credit"},
{id:"commodities",title:t("8 · Commodities: physical markets and financial prices","8 · Matières premières : physique et prix financiers"),goal:t("Distinguish supply shocks, demand shocks and futures returns.","Distinguer chocs d’offre, de demande et rendement des contrats à terme."),sections:[
{title:t("Physical constraints change the story","Les contraintes physiques changent l’analyse"),body:t("Oil, gas, metals and agricultural goods have different production, storage and transport constraints. A demand-driven oil rally can accompany stronger growth, while a supply-disruption rally can raise inflation and hurt consumers. The same price direction can therefore signal different macro outcomes. WTI and Brent refer to different oil benchmarks; natural gas is particularly regional because transport and storage are constrained. Quote units matter: dollars per barrel are not dollars per unit of energy.","Pétrole, gaz, métaux et produits agricoles ont des contraintes de production, stockage et transport distinctes. Une hausse du pétrole tirée par la demande peut accompagner la croissance ; une rupture d’offre peut alimenter l’inflation et pénaliser le consommateur. Le même mouvement de prix raconte donc des histoires différentes. WTI et Brent sont des références distinctes ; le gaz est très régional à cause des infrastructures. Vérifie les unités : dollar par baril et dollar par unité d’énergie diffèrent.")},
{title:t("Spot, futures and rolling a position","Comptant, terme et renouvellement"),body:t("A spot price describes near-term delivery. A futures contract specifies delivery or settlement at a later date. The futures curve reflects storage, financing, convenience yield and market expectations. Contango means later contracts trade above nearer ones; backwardation means the reverse. A fund rolling futures may have returns different from the spot commodity because of roll effects, collateral income and fees. A commodity index is not a warehouse of physical goods you can redeem freely.","Le comptant concerne une livraison proche. Un contrat à terme fixe une livraison ou un règlement ultérieur. La courbe à terme reflète stockage, financement, avantage de disponibilité et attentes. Le contango signifie des contrats éloignés plus chers que les proches ; la backwardation, l’inverse. Un fonds qui renouvelle ses contrats peut diverger du prix comptant à cause du roulement, de la rémunération des garanties et des frais. Un indice matières premières n’est pas un entrepôt librement remboursable en biens physiques.")},
{title:t("Gold and transmission into margins","Or et transmission aux marges"),body:t("Gold has no contractual coupon: real yields can affect its opportunity cost, while currencies, official-sector demand and risk perceptions also matter. There is no fixed rule that gold must rise whenever inflation rises. Higher energy prices can help producers but raise costs for transport, manufacturing and households. The net impact depends on hedging, pricing power and how quickly costs pass through to selling prices.","L’or n’a pas de coupon contractuel : les taux réels influencent son coût d’opportunité, tandis que devises, demande officielle et perception du risque comptent aussi. L’or ne monte pas mécaniquement avec l’inflation. Une énergie plus chère peut aider les producteurs et pénaliser transport, industrie et ménages. L’effet net dépend des couvertures, du pouvoir de fixation des prix et de la vitesse de répercussion des coûts.")}
],terms:[{term:t("Contango","Contango"),definition:t("Later-dated futures trade above nearer-dated contracts.","Les contrats éloignés cotent au-dessus des contrats proches.")},{term:t("Pricing power","Pouvoir de fixation des prix"),definition:t("Ability to pass higher costs through without losing too much demand.","Capacité à répercuter les coûts sans perdre trop de demande.")}],formula:t("Illustrative cost shock = exposed input cost × percentage price increase","Choc de coût illustratif = coût exposé × hausse du prix en %"),example:t("Hypothetical transport firm spends $20m on unhedged fuel. A 10% increase with unchanged volumes adds $2m in annual cost before offsets. It does not mean profit falls 10%: the profit impact depends on its original profit, hedges, efficiency and customer pricing.","Une entreprise de transport dépense fictivement 20 M$ de carburant non couvert. +10 % à volumes constants ajoute 2 M$ de coût avant compensation. Le bénéfice ne baisse pas forcément de 10 % : cela dépend du bénéfice initial, des couvertures, de l’efficacité et des prix clients."),flow:[t("Identify supply vs demand shock","Identifier choc d’offre ou de demande"),t("Check inventories and futures curve","Vérifier stocks et courbe à terme"),t("Trace producer and consumer exposure","Suivre exposition producteurs et consommateurs"),t("Assess margins, inflation and policy response","Évaluer marges, inflation et réponse monétaire")],mistake:t("A commodity ETF’s return need not equal the spot-price change.","Le rendement d’un ETF matières premières n’égale pas forcément la variation du comptant."),question:t("Oil rises because supply is disrupted. Which interpretation is strongest?","Le pétrole monte après une rupture d’offre. Quelle interprétation est la plus solide ?"),options:[t("Input costs may rise even if growth weakens","Les coûts peuvent monter même si la croissance ralentit"),t("Global growth must be booming","La croissance mondiale est forcément forte"),t("All companies benefit","Toutes les entreprises en bénéficient")],correct:0,feedback:t("The cause of the price change matters: reduced supply can be inflationary and growth-negative.","La cause compte : une baisse d’offre peut augmenter l’inflation et pénaliser la croissance."),lesson:"year-1-macroeconomics-for-markets",visual:"none"},
{id:"volatility",title:t("9 · Volatility, VIX and options","9 · Volatilité, VIX et options"),goal:t("Understand uncertainty without confusing it with a directional forecast.","Comprendre l’incertitude sans la confondre avec une prévision de direction."),sections:[
{title:t("Realized and implied volatility","Volatilité réalisée et implicite"),body:t("Realized volatility measures variation in observed returns over a selected historical window. Implied volatility is inferred from option prices using a model or methodology. It reflects pricing of future uncertainty and risk compensation, not a perfect forecast. Options give asymmetric payoffs: a call grants a right to buy, a put a right to sell, subject to strike, expiry and exercise terms. Buying an option can lose the entire premium; selling options can create much larger risks.","La volatilité réalisée mesure la variation des rendements passés sur une période choisie. La volatilité implicite est déduite des prix d’options selon un modèle ou une méthode. Elle reflète l’incertitude future et sa rémunération, sans prédiction parfaite. Une option donne un droit asymétrique : acheter pour un call, vendre pour un put, selon prix d’exercice, échéance et modalités. L’acheteur peut perdre toute la prime ; certaines ventes d’options exposent à des pertes bien supérieures.")},
{title:t("Read the VIX in the right units","Lire le VIX avec les bonnes unités"),body:t("The VIX uses S&P 500 option prices to estimate a constant roughly 30-day expected volatility measure, quoted at an annualized rate. It is not a percentage prediction of the index’s next-day loss. A higher VIX can reflect greater uncertainty or more expensive protection. Convert annualized volatility to a shorter horizon only as a rough scale: the square-root-of-time approximation assumes a simplified return process and understates important features such as jumps and changing volatility.","Le VIX utilise les options S&P 500 pour estimer une volatilité attendue d’environ 30 jours, exprimée en rythme annualisé. Ce n’est pas la perte attendue de l’indice le lendemain. Une hausse peut refléter incertitude accrue ou protection plus chère. La conversion vers une période courte n’est qu’un ordre de grandeur : la racine du temps suppose un processus simplifié et ignore notamment sauts et changements de volatilité.")},
{title:t("Risk is broader than volatility","Le risque dépasse la volatilité"),body:t("Permanent capital loss, illiquidity, leverage, concentration, default and model error are risks even when recent prices appear calm. Correlations can shift during stress. A strategy that makes small profits steadily may conceal rare large losses. Read volatility together with equity breadth, credit spreads, financing conditions and the position’s payoff structure. VIX exposure through futures products also differs from holding the VIX index itself.","Perte permanente, illiquidité, levier, concentration, défaut et erreur de modèle restent des risques même si les prix récents sont calmes. Les corrélations changent en période de stress. Une stratégie régulièrement rentable peut cacher des pertes rares très importantes. Lis volatilité, participation actions, spreads, financement et structure du gain ensemble. Les produits à terme VIX ne reproduisent pas simplement l’indice VIX.")}
],terms:[{term:t("Implied volatility","Volatilité implicite"),definition:t("Volatility inferred from option prices, including market pricing of uncertainty.","Volatilité déduite des prix d’options et de la rémunération de l’incertitude.")},{term:t("Drawdown","Repli depuis un sommet"),definition:t("Decline from a previous portfolio or asset peak.","Baisse depuis un précédent sommet de portefeuille ou d’actif.")}],formula:t("Rough horizon volatility ≈ annual volatility × √(days / 365)","Volatilité indicative ≈ volatilité annuelle × √(jours / 365)"),example:t("Hypothetical annualized volatility of 20% gives roughly 20% × √(30/365) = 5.73% over 30 calendar days. It is an uncertainty scale, not a guaranteed range or directional prediction; actual outcomes can lie far outside it.","Une volatilité annualisée hypothétique de 20 % donne environ 20 % × √(30/365) = 5,73 % sur 30 jours calendaires. C’est une échelle d’incertitude, pas un intervalle garanti ni une direction ; les résultats peuvent largement dépasser cet ordre de grandeur."),flow:[t("Investors reassess uncertainty","Les investisseurs réévaluent l’incertitude"),t("Option prices and protection demand change","Les prix d’options et la demande de protection changent"),t("Implied volatility reprices","La volatilité implicite s’ajuste"),t("Read alongside credit and equity evidence","Comparer avec crédit et actions")],mistake:t("VIX 25 does not mean the S&P 500 will fall 25%.","VIX à 25 ne signifie pas que le S&P 500 va perdre 25 %."),question:t("Does a higher VIX specify whether equities will rise or fall next?","Un VIX plus élevé donne-t-il la direction suivante des actions ?"),options:[t("No, it measures priced uncertainty rather than direction","Non, il mesure l’incertitude valorisée"),t("Yes, always down","Oui, toujours une baisse"),t("Yes, always up","Oui, toujours une hausse")],correct:0,feedback:t("Volatility describes the scale of fluctuations, not a guaranteed directional move.","La volatilité décrit l’amplitude des fluctuations, pas un mouvement directionnel garanti."),lesson:"year-2-options-option-greeks",visual:"risk"},
{id:"macro",title:t("10 · Read an economic release like an analyst","10 · Lire une publication macro comme un analyste"),goal:t("Distinguish the reported level, the surprise, revisions and transmission.","Distinguer niveau publié, surprise, révisions et transmission."),sections:[
{title:t("Markets react to new information","Les marchés réagissent à l’information nouvelle"),body:t("A release has a level, a rate of change, a comparison period and often revisions to previous data. Year-on-year and month-on-month inflation can send different signals because base effects matter. Compare actual data with a documented pre-release consensus, not an invented expectation. A strong economy can still produce a negative price reaction if investors expected even stronger growth or if the news implies tighter policy.","Une publication a un niveau, un rythme de variation, une période de comparaison et souvent des révisions. Inflation annuelle et mensuelle peuvent diverger à cause des effets de base. Compare les données avec un consensus documenté avant publication, pas une attente inventée. Une économie forte peut produire une réaction négative si le marché attendait mieux ou anticipe une politique plus restrictive.")},
{title:t("Central banks influence, but do not set every yield","Les banques centrales influencent les taux"),body:t("Policy tools affect short-term financing conditions, expectations and balance sheets. Transmission to lending, demand and inflation takes time and varies across borrowers. Long-term yields remain market prices affected by future policy expectations, supply and term premiums. A policy rate cut can coexist with higher long-term yields if inflation or term-premium concerns rise. Distinguish the policy decision from guidance about the future path.","Les outils monétaires affectent financement court, anticipations et bilans. La transmission au crédit, à la demande et à l’inflation prend du temps et varie selon les emprunteurs. Les taux longs restent des prix de marché influencés par trajectoire future, offre et prime de terme. Une baisse du taux directeur peut coexister avec des taux longs plus élevés si inflation ou prime de terme inquiètent. Distingue décision et communication sur la trajectoire future.")},
{title:t("Build competing explanations","Construire des explications concurrentes"),body:t("For a hotter inflation release, one possible chain is fewer expected cuts, higher front-end yields, a stronger currency and valuation pressure. Another is that weak underlying demand outweighs the headline, changing the later reaction. Check components, revisions, positioning and other simultaneous news. Observing prices move together does not prove which event caused them. Write down what additional evidence would make you revise the interpretation.","Après une inflation supérieure aux attentes, un scénario possible est : moins de baisses anticipées, taux courts plus élevés, devise plus forte et pression sur les valorisations. Mais une demande sous-jacente faible peut dominer ensuite. Vérifie composantes, révisions, positionnement et autres annonces simultanées. Des prix qui bougent ensemble ne prouvent pas une causalité. Note les éléments qui te feraient réviser l’analyse.")}
],terms:[{term:t("Consensus","Consensus"),definition:t("Documented aggregate expectation before a release.","Attente agrégée documentée avant une publication.")},{term:t("Real rate","Taux réel"),definition:t("Interest rate adjusted for expected or realized inflation, with the convention stated.","Taux ajusté de l’inflation attendue ou réalisée, selon une convention explicite.")}],formula:t("Surprise = actual release − pre-release consensus","Surprise = valeur publiée − consensus avant publication"),example:t("Illustration: expected annual inflation 3.0%, actual 3.3% gives a +0.3 percentage-point surprise. This is not proof that rates will rise: core components, prior revisions and what policy makers prioritize can alter the interpretation.","Illustration : inflation annuelle attendue 3,0 %, publiée 3,3 % : surprise de +0,3 point. Ce n’est pas la preuve d’une hausse des taux : composantes sous-jacentes, révisions et priorités monétaires peuvent modifier la lecture."),flow:[t("Release vs documented expectation","Publication vs attente documentée"),t("Revise growth and inflation assessment","Réviser croissance et inflation"),t("Reprice the policy path and discount rates","Réévaluer trajectoire monétaire et actualisation"),t("Test cross-asset reactions and alternatives","Tester réactions multi-actifs et alternatives")],mistake:t("Good economic news is not automatically good stock-market news.","Une bonne nouvelle économique n’est pas automatiquement bonne pour les actions."),question:t("Inflation is 3.3%, expected 3.0%. What is known?","Inflation 3,3 %, attendue 3,0 %. Que sait-on ?"),options:[t("The release exceeded consensus by 0.3 percentage point","La publication dépasse le consensus de 0,3 point"),t("Equities must fall","Les actions vont forcément baisser"),t("The central bank must hike tomorrow","La banque centrale doit relever ses taux demain")],correct:0,feedback:t("Only the measured surprise is established. Policy and price reactions require further evidence.","Seule la surprise mesurée est établie. Politique et réactions de prix exigent d’autres preuves."),lesson:"year-1-macroeconomics-for-markets",visual:"none"},
{id:"portfolio",title:t("11 · Turn market knowledge into portfolio discipline","11 · Passer des marchés à la discipline de portefeuille"),goal:t("Connect risk, diversification, position size and attribution.","Relier risque, diversification, taille de position et attribution."),sections:[
{title:t("A position is part of a system","Une position appartient à un ensemble"),body:t("Diversification depends on economic exposures and correlations, not simply the number of ticker symbols. Ten technology stocks can share the same rate and earnings risks. A bond fund and a growth-stock fund may both suffer when real yields rise. Define the investment horizon, base currency, liquidity needs and acceptable losses before comparing assets. Leverage can magnify losses and trigger forced liquidation before a thesis has time to work.","La diversification dépend des expositions et corrélations, pas du nombre de symboles. Dix valeurs technologiques peuvent partager les mêmes risques de taux et de bénéfices. Un fonds obligataire et un fonds de croissance peuvent souffrir ensemble lorsque les taux réels montent. Définis horizon, devise de référence, besoin de liquidité et pertes acceptables. Le levier amplifie les pertes et peut imposer une liquidation avant que la thèse se réalise.")},
{title:t("Measure contribution, not just the winning asset","Mesurer les contributions"),body:t("For beginning-of-period weights without interim trades, portfolio return is the weighted sum of component total returns in a consistent currency. Contribution identifies what drove the result. A large gain in a tiny position can contribute less than a small loss in a large position. Rebalancing restores desired exposures but has costs and potential tax consequences. Historical volatility and correlations are estimates that may change.","Avec des pondérations de début de période et sans transactions intermédiaires, le rendement du portefeuille est la somme pondérée des rendements totaux dans une devise cohérente. La contribution identifie les moteurs du résultat. Un fort gain sur une petite position peut peser moins qu’une petite perte sur une grosse. Rééquilibrer restaure les expositions mais entraîne coûts et conséquences fiscales éventuelles. Volatilités et corrélations historiques restent des estimations.")},
{title:t("Test a thesis and record the invalidation condition","Tester une thèse et son invalidation"),body:t("A useful thesis specifies a mechanism, evidence, catalyst, valuation assumption and what would prove it wrong. Separate price movement from evidence about the business. A good outcome can come from poor reasoning and a loss can occur despite a sensible probabilistic process. Review both. In the Investing Lab, use simulated positions to test arithmetic and decision discipline before judging skill from a handful of outcomes.","Une thèse utile précise mécanisme, preuves, catalyseur, hypothèse de valorisation et invalidation. Sépare mouvement de prix et information sur l’entreprise. Un bon résultat peut venir d’un mauvais raisonnement ; une perte peut suivre un processus probabiliste sensé. Évalue les deux. Dans le laboratoire, utilise des positions simulées pour travailler calculs et discipline avant de déduire ta compétence de quelques résultats.")}
],terms:[{term:t("Position sizing","Dimensionnement de position"),definition:t("Choosing exposure so a plausible loss fits a defined portfolio risk budget.","Choisir l’exposition pour qu’une perte plausible respecte un budget de risque.")},{term:t("Attribution","Attribution de performance"),definition:t("Decomposing portfolio results into contributions from exposures and decisions.","Décomposer le résultat en contributions des expositions et décisions.")}],formula:t("Portfolio return = Σ(weight × component return); illustrative position weight = risk budget / loss scenario","Rendement portefeuille = Σ(poids × rendement) ; poids illustratif = budget de risque / perte du scénario"),example:t("Illustration: 60% in equities returning +8%, 40% in bonds returning −3% gives 0.60×8% + 0.40×(−3%) = +3.6%. A 10% position losing 20% contributes roughly −2 percentage points to the portfolio before other changes.","Illustration : 60 % d’actions à +8 %, 40 % d’obligations à −3 % donnent 0,60×8 % + 0,40×(−3 %) = +3,6 %. Une position de 10 % qui perd 20 % contribue environ −2 points au portefeuille, avant autres changements."),flow:[t("Define hypothesis and evidence","Définir hypothèse et preuves"),t("Set loss scenario and exposure","Fixer scénario de perte et exposition"),t("Observe outcomes and catalysts","Observer résultats et catalyseurs"),t("Review reasoning and attribution","Revoir raisonnement et contributions")],mistake:t("Diversification reduces some risks; it cannot eliminate all losses.","La diversification réduit certains risques ; elle n’élimine pas toutes les pertes."),question:t("A 5% position falls 20%. Approximate portfolio contribution?","Une position de 5 % perd 20 %. Contribution approximative au portefeuille ?"),options:[t("−1 percentage point","−1 point de pourcentage"),t("−20 percentage points","−20 points"),t("−100 percentage points","−100 points")],correct:0,feedback:t("0.05 × −20% = −1%. The position’s loss and its portfolio contribution are different quantities.","0,05 × −20 % = −1 %. La perte de la position et sa contribution sont distinctes."),lesson:"year-1-risk-return-diversification",visual:"allocation"},
{id:"case-study",title:t("12 · Final case: build a cross-asset market brief","12 · Cas final : construire une analyse multi-actifs"),goal:t("Integrate observation, arithmetic, mechanisms, alternative scenarios and a clear conclusion.","Réunir observation, calculs, mécanismes, scénarios alternatifs et conclusion claire."),sections:[
{title:t("Start from a hypothetical evidence pack","Partir d’un dossier de données fictif"),body:t("Suppose inflation is reported at 3.3% versus a documented 3.0% expectation. Over a comparable window, 2Y yield rises from 4.00% to 4.25%, 10Y from 4.20% to 4.30%, a stock index loses 1%, the dollar strengthens and high-yield spreads widen 20 bps. These inputs are an educational scenario, not today’s observations. Calculate first: 2Y +25 bps, 10Y +10 bps, slope from +20 to +5 bps. This is bear flattening by 15 bps.","Suppose une inflation publiée à 3,3 % contre 3,0 % attendu. Sur une période comparable, le 2 ans passe de 4,00 % à 4,25 %, le 10 ans de 4,20 % à 4,30 %, un indice actions perd 1 %, le dollar se renforce et le spread haut rendement augmente de 20 bps. Ces données sont fictives. Calculer d’abord : 2 ans +25 bps, 10 ans +10 bps, pente de +20 à +5 bps. C’est un bear flattening de 15 bps.")},
{title:t("Explain a plausible mechanism and test it","Expliquer un mécanisme plausible et le tester"),body:t("One explanation is that investors price a tighter future policy path. Higher discount rates can reduce equity present values and relative yield changes can support the dollar. Wider credit spreads could reflect concern that tighter conditions hurt weaker borrowers. But simultaneity is not proof. Check whether the inflation surprise, positioning, earnings news, auction supply or another event best explains the timing. For a duration-5 bond, +10 bps suggests roughly −0.5% from that yield shift alone.","Une explication possible est une trajectoire monétaire plus restrictive anticipée. L’actualisation peut peser sur les actions et les différentiels de taux soutenir le dollar. Les spreads peuvent refléter l’inquiétude pour les emprunteurs fragiles. Mais simultanéité n’est pas preuve. Vérifie si inflation, positionnement, résultats, émission obligataire ou autre événement expliquent le calendrier. Pour une obligation de duration 5, +10 bps suggère environ −0,5 % du seul effet de taux.")},
{title:t("State scenarios and what changes your mind","Énoncer scénarios et conditions de révision"),body:t("Base case: persistent inflation keeps financing conditions restrictive; monitor subsequent core inflation, wages and central-bank communication. Alternative: a temporary component caused the surprise and growth weakens, reversing the rate move. Adverse case for risky assets: inflation remains sticky while growth deteriorates and credit losses rise. Avoid attaching precise probabilities without a method. End a brief with the key uncertainty, the next dated evidence to verify and how that evidence would alter the thesis.","Scénario central : inflation persistante et financement restrictif ; suivre inflation sous-jacente, salaires et communication monétaire. Alternative : composante temporaire et ralentissement inversent le mouvement de taux. Scénario défavorable aux actifs risqués : inflation persistante, croissance faible et pertes de crédit. N’attribue pas de probabilités précises sans méthode. Termine par incertitude principale, prochaine preuve datée à vérifier et son effet sur la thèse.")}
],terms:[{term:t("Catalyst","Catalyseur"),definition:t("An identifiable event that could reveal information or change pricing.","Événement identifiable pouvant révéler une information ou modifier les prix.")},{term:t("Invalidation","Invalidation"),definition:t("Evidence that contradicts the mechanism or assumptions of a thesis.","Preuve contredisant le mécanisme ou les hypothèses d’une thèse.")}],formula:t("Brief = observation + calculation + mechanism + alternative + next evidence","Analyse = observation + calcul + mécanisme + alternative + prochaine preuve"),example:t("Sample synthesis: ‘A +0.3 pp inflation surprise coincided with front-end-led yield increases and bear flattening. Tighter policy expectations are a plausible driver, but component details and other news need checking. Watch whether subsequent data confirms persistence; otherwise the move may reverse.’","Synthèse : « Une surprise d’inflation de +0,3 point coïncide avec une hausse des taux menée par le court et un bear flattening. Une trajectoire monétaire plus restrictive est plausible, mais il faut vérifier composantes et autres annonces. Les données suivantes confirmeront ou infirmeront la persistance ; sinon, le mouvement peut s’inverser. »"),flow:[t("State sourced observations","Énoncer observations sourcées"),t("Show arithmetic with units","Montrer les calculs et unités"),t("Explain a conditional mechanism","Expliquer un mécanisme conditionnel"),t("Specify alternative and invalidation","Préciser alternative et invalidation"),t("Name the next evidence to verify","Nommer la prochaine preuve à vérifier")],mistake:t("An elegant causal story is not evidence that the cause has been identified.","Un récit causal élégant ne prouve pas que la cause a été identifiée."),question:t("2Y +25 bps and 10Y +10 bps: what happens to 2s10s?","2 ans +25 bps et 10 ans +10 bps : que devient le 2s10s ?"),options:[t("It falls 15 bps: bear flattening","Il baisse de 15 bps : bear flattening"),t("It rises 35 bps","Il monte de 35 bps"),t("It stays unchanged","Il reste inchangé")],correct:0,feedback:t("Change in spread = +10 − (+25) = −15 bps; both yields rise, so it is bear flattening.","Variation de pente = +10 − (+25) = −15 bps ; les rendements montent, donc bear flattening."),lesson:"year-3-sales-trading",visual:"curve"}
];
